'use strict';

const fs = require('node:fs');

const mode = process.env.BEHAVIORLOCK_RESOURCE_MODE;

function fail(message) {
  process.stderr.write(`${message}\n`);
  process.exit(73);
}

function markBoundary(path) {
  fs.writeFileSync(path, 'boundary reached\n');
  process.exit(73);
}

function exhaustMemory() {
  const retained = [];
  for (;;) {
    retained.push(Buffer.alloc(8 * 1024 * 1024, 0x41));
  }
}

function exhaustDescriptors() {
  const descriptors = [];
  for (;;) {
    try {
      descriptors.push(fs.openSync('/dev/null', 'r'));
    } catch (error) {
      if (error.code === 'EMFILE') {
        fs.closeSync(descriptors.pop());
        markBoundary('/work/behaviorlock-descriptor-boundary');
      }
      throw error;
    }
  }
}

function exhaustWorkTmpfs() {
  const chunk = Buffer.alloc(1024 * 1024, 0x42);
  const descriptor = fs.openSync('/work/behaviorlock-resource-fill', 'w');
  for (;;) {
    try {
      fs.writeSync(descriptor, chunk);
    } catch (error) {
      if (error.code === 'ENOSPC') markBoundary('/tmp/behaviorlock-tmpfs-boundary');
      throw error;
    }
  }
}

function exhaustFileSize() {
  const chunk = Buffer.alloc(1024 * 1024, 0x43);
  const descriptor = fs.openSync('/work/behaviorlock-file-limit', 'w');
  const reached = () => markBoundary('/work/behaviorlock-file-boundary');
  process.once('SIGXFSZ', reached);
  for (;;) {
    try {
      fs.writeSync(descriptor, chunk);
    } catch (error) {
      if (error.code === 'EFBIG') reached();
      throw error;
    }
  }
}

function exhaustOutput() {
  const chunk = Buffer.alloc(1024 * 1024, 0x44);
  function write() {
    while (process.stdout.write(chunk)) {
      // Continue until the bounded output filesystem rejects or backpressures writes.
    }
    process.stdout.once('drain', write);
  }
  process.stdout.on('error', (error) => {
    if (error.code === 'ENOSPC' || error.code === 'EFBIG') {
      markBoundary('/work/behaviorlock-output-boundary');
    }
    throw error;
  });
  write();
}

function exhaustTraceVolume() {
  for (let index = 0; index < 2_000_000; index += 1) {
    try {
      fs.statSync('/etc/hosts');
    } catch (_) {
      // The tracer boundary, not the stat result, is under test.
    }
  }
}

switch (mode) {
case 'memory':
  exhaustMemory();
  break;
case 'descriptor':
  exhaustDescriptors();
  break;
case 'tmpfs':
  exhaustWorkTmpfs();
  break;
case 'file':
  exhaustFileSize();
  break;
case 'output':
  exhaustOutput();
  break;
case 'syscall':
  exhaustTraceVolume();
  break;
case 'timeout':
  setTimeout(() => process.exit(0), 60_000);
  break;
default:
  fail(`unknown resource fixture mode: ${mode || 'missing'}`);
}
